parameters.jsCode:
// Group matches by user and construct professional personalized HTML emails
// Complies strictly with the assignment rule: maps to controlled test inbox alias!
const rows = $input.all().map(i => i.json);
if (!rows || rows.length === 0) {
  return [];
}

const testInboxBase = $env.TEST_EMAIL_RECIPIENT || 'test.applicant.clickpe@gmail.com';

// Group by user_id
const usersMap = {};
for (const r of rows) {
  if (!usersMap[r.user_id]) {
    usersMap[r.user_id] = {
      user_id: r.user_id,
      original_email: r.email,
      job_id: r.job_id,
      credit_score: r.credit_score,
      monthly_income: r.monthly_income,
      eligibility_reason: r.eligibility_reason,
      offers: []
    };
  }
  usersMap[r.user_id].offers.push({
    provider_name: r.provider_name,
    product_name: r.product_name,
    interest_rate: r.interest_rate,
    max_loan_amount: r.max_loan_amount,
    match_score: r.match_score
  });
}

const emailJobs = [];
let userCounter = 1;

for (const userId in usersMap) {
  const u = usersMap[userId];

  // Generate test inbox alias e.g. base+user1@gmail.com
  let targetEmail = testInboxBase;
  if (testInboxBase.includes('@')) {
    const [localPart, domain] = testInboxBase.split('@');
    targetEmail = `${localPart}+user${userCounter}@${domain}`;
  }
  userCounter++;

  // Build styled HTML table of matched loan offers
  const offerRows = u.offers.map(o => `
    <tr style="border-bottom: 1px solid #e2e8f0;">
      <td style="padding: 12px; font-weight: bold; color: #1e293b;">${o.provider_name}</td>
      <td style="padding: 12px; color: #475569;">${o.product_name}</td>
      <td style="padding: 12px; font-weight: 600; color: #16a34a;">${o.interest_rate}% p.a.</td>
      <td style="padding: 12px; color: #475569;">₹${parseFloat(o.max_loan_amount).toLocaleString('en-IN')}</td>
      <td style="padding: 12px;"><span style="background: #dcfce7; color: #15803d; padding: 4px 8px; border-radius: 9999px; font-size: 12px; font-weight: bold;">${o.match_score}% Match</span></td>
    </tr>
  `).join('');

  const htmlContent = `
    <!DOCTYPE html>
    <html>
    <head><meta charset="utf-8"></head>
    <body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #f8fafc; padding: 24px;">
      <div style="max-width: 640px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; border: 1px solid #e2e8f0; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);">
        <div style="background: #2563eb; padding: 24px; color: #ffffff;">
          <h1 style="margin: 0; font-size: 22px;">Personal Loan Pre-Approval Notice</h1>
          <p style="margin: 6px 0 0 0; opacity: 0.9; font-size: 14px;">Tailored offers for Applicant ID: <strong>${u.user_id}</strong></p>
        </div>
        <div style="padding: 24px;">
          <div style="background: #eff6ff; border-left: 4px solid #3b82f6; padding: 16px; border-radius: 4px; margin-bottom: 24px;">
            <p style="margin: 0; font-size: 14px; color: #1e40af; line-height: 1.5;">
              <strong>Underwriting Summary:</strong> ${u.eligibility_reason || 'You have met credit and income qualifications for top-tier personal loans.'}
            </p>
          </div>
          <h3 style="color: #0f172a; margin-top: 0;">Your Matched Loan Products:</h3>
          <table style="width: 100%; border-collapse: collapse; text-align: left; font-size: 14px;">
            <thead>
              <tr style="background: #f1f5f9; color: #475569;">
                <th style="padding: 10px;">Lender</th>
                <th style="padding: 10px;">Product</th>
                <th style="padding: 10px;">Rate</th>
                <th style="padding: 10px;">Max Amount</th>
                <th style="padding: 10px;">Fit</th>
              </tr>
            </thead>
            <tbody>${offerRows}</tbody>
          </table>
          <div style="margin-top: 28px; text-align: center;">
            <a href="https://clickpe.in" style="background: #2563eb; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 8px; font-weight: 600; font-size: 15px; display: inline-block;">Claim Pre-Approved Offer</a>
          </div>
        </div>
        <div style="background: #f8fafc; padding: 16px; text-align: center; font-size: 12px; color: #64748b; border-top: 1px solid #e2e8f0;">
          Sent via The Loan Eligibility Engine | ClickPe / DailyPe Engineering Assignment Demo
        </div>
      </div>
    </body>
    </html>
  `;

  emailJobs.push({
    json: {
      job_id: u.job_id,
      user_id: u.user_id,
      to_email: targetEmail,
      original_email: u.original_email,
      subject: `Pre-Approved Personal Loan Offers for ${u.user_id}`,
      html_body: htmlContent
    }
  });
}

return emailJobs;

parameters.query:
UPDATE matches 
SET is_notified = TRUE, notified_at = NOW() 
WHERE job_id = $1::uuid;
